using FiscoProjects.Persistence.Auditing;
using FiscoProjects.SharedKernel;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Infrastructure;

namespace FiscoProjects.Persistence;

/// <summary>
/// Base context of every module. Puts the module tables in its own schema and applies the shared
/// conventions: date and time in UTC and entity ids generated by the application. Every save is audited
/// here, in the same transaction as the changes (ADR-0039, ADR-0075).
/// </summary>
public abstract class ModuleDbContext<TSelf>(DbContextOptions<TSelf> options) : DbContext(options)
    where TSelf : ModuleDbContext<TSelf>, IModuleSchema
{
    /// <summary>False only for the context that writes the audit itself.</summary>
    protected virtual bool IsAudited => true;

    /// <summary>Saves are asynchronous end to end, and this is the only way they are audited.</summary>
    public sealed override int SaveChanges(bool acceptAllChangesOnSuccess) =>
        throw new NotSupportedException("Use SaveChangesAsync: saves are asynchronous and audited (ADR-0039).");

    /// <summary>
    /// Saves the changes and their audit records together. Inside a transaction of the module, both go in it;
    /// otherwise a transaction is opened in the retry strategy, so a transient failure repeats both.
    /// </summary>
    public override async Task<int> SaveChangesAsync(bool acceptAllChangesOnSuccess, CancellationToken cancellationToken = default)
    {
        var auditor = IsAudited ? FindAuditor() : null;
        var changes = auditor is null ? [] : ChangeCapture.Capture(ChangeTracker, TSelf.Schema);
        if (auditor is null || changes.Count == 0)
        {
            return await base.SaveChangesAsync(acceptAllChangesOnSuccess, cancellationToken);
        }

        int saved;
        if (Database.CurrentTransaction is not null)
        {
            saved = await SaveWithAuditAsync(auditor, changes, cancellationToken);
        }
        else
        {
            saved = await Database.CreateExecutionStrategy().ExecuteAsync(async () =>
            {
                await using var transaction = await Database.BeginTransactionAsync(cancellationToken);
                var count = await SaveWithAuditAsync(auditor, changes, cancellationToken);
                await transaction.CommitAsync(cancellationToken);
                return count;
            });
        }

        if (acceptAllChangesOnSuccess)
        {
            ChangeTracker.AcceptAllChanges();
        }

        return saved;
    }

    private async Task<int> SaveWithAuditAsync(IChangeAuditor auditor, IReadOnlyList<AuditedChange> changes, CancellationToken cancellationToken)
    {
        var count = await base.SaveChangesAsync(acceptAllChangesOnSuccess: false, cancellationToken);
        await auditor.RecordAsync(this, changes, cancellationToken);
        return count;
    }

    /// <summary>The audit writer registered by the application, if any; a module tested alone saves without it.</summary>
    private IChangeAuditor? FindAuditor() =>
        this.GetService<IDbContextOptions>()
            .FindExtension<CoreOptionsExtension>()?
            .ApplicationServiceProvider?
            .GetService(typeof(IChangeAuditor)) as IChangeAuditor;

    protected sealed override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.HasDefaultSchema(TSelf.Schema);
        ConfigureModel(modelBuilder);
        UseApplicationGeneratedIds(modelBuilder);
    }

    /// <summary>Entity mappings of the module.</summary>
    protected abstract void ConfigureModel(ModelBuilder modelBuilder);

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        configurationBuilder.Properties<DateTime>().HaveConversion<UtcDateTimeConverter>();
        configurationBuilder.Properties<DateTime?>().HaveConversion<UtcDateTimeConverter>();
    }

    private static void UseApplicationGeneratedIds(ModelBuilder modelBuilder)
    {
        var entities = modelBuilder.Model.GetEntityTypes()
            .Where(entityType => typeof(Entity).IsAssignableFrom(entityType.ClrType) && entityType.BaseType is null);

        foreach (var entityType in entities)
        {
            modelBuilder.Entity(entityType.ClrType).Property(nameof(Entity.Id)).ValueGeneratedNever();
        }
    }
}
